static void Prepare(const std::string& dir){Reset(dir);auto e=HouseClass::As_Pointer(HOUSE_BAD);e->IsActive=true;e->IsDefeated=false;e->Credits=200000;e->Tiberium=0;e->Capacity=100000;}
static int EnemyCount(){int n=0;for(int i=0;i<Units.Count();++i){auto u=Units.Ptr(i);if(!u->IsInLimbo&&u->House==HouseClass::As_Pointer(HOUSE_BAD))++n;}return n;}
static HouseClass* Enemy(){return HouseClass::As_Pointer(HOUSE_BAD);}
static BuildingClass* MakeYard(const std::string& dir){Prepare(dir);auto b=new BuildingClass(STRUCT_CONST,HOUSE_BAD);Check("place enemy construction yard",Put(b,Center()));Enemy()->IsStarted=true;return b;}
static int CountBuilding(StructType t){int n=0;for(int i=0;i<Buildings.Count();++i){auto b=Buildings.Ptr(i);if(!b->IsInLimbo&&b->House==Enemy()&&b->Class->Type==t)++n;}return n;}
static int Walls(){int n=0;for(int i=0;i<MAP_CELL_TOTAL;++i)if(Map[i].Overlay==OVERLAY_BRICK_WALL&&Map[i].Owner==HOUSE_BAD)++n;return n;}
static void DistanceRule(const std::string& dir){auto b=MakeYard(dir);CELL c=Coord_Cell(b->Coord);auto offsets=b->Occupy_List(true);int right=Cell_X(c);for(auto p=offsets;*p!=REFRESH_EOL;++p)if(Cell_Y(c+*p)==Cell_Y(c))right=MAX(right,Cell_X(c+*p));CELL ten=XY_Cell(right+10,Cell_Y(c)),eleven=XY_Cell(right+11,Cell_Y(c));Check("AI construction includes ten cells from own footprint",Campaign_Expansion_Near(Enemy(),ten));Check("AI construction excludes eleven cells from own footprint",!Campaign_Expansion_Near(Enemy(),eleven));auto turret=new BuildingClass(STRUCT_TURRET,HOUSE_BAD);bool nativeInside=false,nativeOutside=false;for(int y=Map.MapCellY;y<Map.MapCellY+Map.MapCellHeight;++y)for(int x=Map.MapCellX;x<Map.MapCellX+Map.MapCellWidth;++x){CELL t=XY_Cell(x,y);if(!turret->Class->Legal_Placement(t))continue;int d=100000;for(auto p=offsets;*p!=REFRESH_EOL;++p){int dx=Cell_X(c+*p)-x,dy=Cell_Y(c+*p)-y;d=MIN(d,dx*dx+dy*dy);}if(d==100)nativeInside|=turret->Passes_Proximity_Check(t)&&Map.Passes_Proximity_Check(&BuildingTypeClass::As_Reference(STRUCT_TURRET),HOUSE_BAD,turret->Occupy_List(true),t);if(d==121)nativeOutside|=!turret->Passes_Proximity_Check(t)&&!Map.Passes_Proximity_Check(&BuildingTypeClass::As_Reference(STRUCT_TURRET),HOUSE_BAD,turret->Occupy_List(true),t);}Check("native building and display placement accept ten cells",nativeInside);Check("native building and display placement reject eleven cells",nativeOutside);delete turret;Check("enemy cannot use player or ally proximity",!Campaign_Expansion_Near(PlayerPtr,ten));GameToPlay=GAME_SKIRMISH;Check("campaign proximity does not affect skirmish",!Campaign_Expansion_Near(Enemy(),ten));GameToPlay=GAME_NORMAL;}
static void Construction(const std::string& dir){auto yard=MakeYard(dir);int start=Enemy()->Available_Money(),walls=Walls(),defenses=0;auto begin=std::chrono::steady_clock::now();
 for(int batch=0;batch<38;++batch){auto type=Enemy()->Suggest_New_Object(RTTI_BUILDINGTYPE);Check("campaign AI selects paid construction without fixed blueprint",type!=nullptr);if(!type)break;auto f=new FactoryClass;Check("queue selected real building",f->Set(*type,*Enemy())&&f->Start());for(int tick=0;tick<50000&&!f->Has_Completed();++tick){++Frame;f->AI();}Check("paid building finishes",f->Has_Completed());auto object=f->Get_Object();int result=yard->Exit_Object(object);Check("completed building legally exits yard",result==2);if(result!=2){delete f;break;}f->Completed();delete f;}
 for(auto t:{STRUCT_TURRET,STRUCT_OBELISK,STRUCT_SAM})defenses+=CountBuilding(t);
 std::printf("FORTRESS ref=%d factory=%d defense=%d wall=%d spent=%d ms=%lld\n",CountBuilding(STRUCT_REFINERY),CountBuilding(STRUCT_AIRSTRIP),defenses,Walls()-walls,start-Enemy()->Available_Money(),(long long)std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-begin).count());
 Check("enemy expands refineries and production facilities",CountBuilding(STRUCT_REFINERY)>=2&&CountBuilding(STRUCT_AIRSTRIP)>=2&&CountBuilding(STRUCT_HAND)>=2);Check("enemy builds numerous basic and heavy defensive towers",defenses>=6);Check("enemy builds concrete wall perimeter segments",Walls()-walls>=8);Check("construction spends real funds",Enemy()->Available_Money()<start);
 Check("expanded base saves",Save_Game((dir+"/fortress.sav").c_str(),"PAID EXPANDING FORTRESS"));Check("expanded base reloads",Load_Game((dir+"/fortress.sav").c_str()));Check("concrete ownership survives reload",Walls()>=walls+8);
}
static void GdiFortress(const std::string& dir){Prepare(dir);auto gdi=HouseClass::As_Pointer(HOUSE_GOOD),nod=HouseClass::As_Pointer(HOUSE_BAD);PlayerPtr=nod;nod->IsHuman=true;gdi->IsHuman=false;gdi->IsActive=true;gdi->IsDefeated=false;gdi->Credits=200000;gdi->Tiberium=0;auto yard=new BuildingClass(STRUCT_CONST,HOUSE_GOOD);Check("place GDI enemy construction yard",Put(yard,Center()));int heavy=0,basic=0,production=0,walls=0;
 for(int batch=0;batch<38;++batch){auto type=gdi->Suggest_New_Object(RTTI_BUILDINGTYPE);if(!type){Check("GDI enemy selects its own faction buildings",false);break;}auto building=static_cast<BuildingTypeClass const*>(type);StructType kind=building->Type;auto f=new FactoryClass;Check("queue GDI fortress construction",f->Set(*type,*gdi)&&f->Start());for(int tick=0;tick<50000&&!f->Has_Completed();++tick){++Frame;f->AI();}int result=yard->Exit_Object(f->Get_Object());Check("GDI fortress building leaves paid factory",result==2);if(result!=2){delete f;break;}f->Completed();delete f;if(kind==STRUCT_ATOWER)++heavy;if(kind==STRUCT_GTOWER)++basic;if(kind==STRUCT_WEAP)++production;if(kind==STRUCT_BRICK_WALL)++walls;}
 Check("GDI enemy erects guard towers, advanced towers, war factories and concrete walls",heavy>=2&&basic>=3&&production>=2&&walls>=8);
}
static void AutonomousBuildings(const std::string& dir){auto yard=MakeYard(dir);Enemy()->IsStarted=false;Enemy()->Power=0;Enemy()->Drain=0;Campaign_Expansion_AI();Check("construction-yard-only enemy is activated",Enemy()->IsStarted);yard->Assign_Mission(MISSION_GUARD);yard->Commence();int before=Buildings.Count(),money=Enemy()->Available_Money();
 for(int tick=0;tick<50000&&CountBuilding(STRUCT_POWER)+CountBuilding(STRUCT_ADVANCED_POWER)==0;++tick){++Frame;std::vector<FactoryClass*> factories;for(int i=0;i<Factories.Count();++i)factories.push_back(Factories.Ptr(i));for(auto f:factories)f->AI();yard->AI();}
 Check("native construction-yard AI buys and places refinery and power without scripted nodes",CountBuilding(STRUCT_REFINERY)>0&&CountBuilding(STRUCT_POWER)+CountBuilding(STRUCT_ADVANCED_POWER)>0&&Enemy()->Available_Money()<money);
}
static void WideExit(const std::string& dir,bool player){Prepare(dir);auto house=player?HOUSE_GOOD:HOUSE_BAD;auto producer=new BuildingClass(player?STRUCT_WEAP:STRUCT_AIRSTRIP,house);Check("place vehicle production facility",Put(producer,Center()));auto p=new UnitClass(UNIT_LTANK,house);auto center=Coord_Cell(producer->Center_Coord());
 std::vector<std::pair<CELL,OverlayType>> restore;for(int dy=-4;dy<=4;++dy)for(int dx=-4;dx<=4;++dx){CELL c=XY_Cell(Cell_X(center)+dx,Cell_Y(center)+dy);if(!Map.In_Radar(c)||Map[c].Cell_Building())continue;restore.emplace_back(c,Map[c].Overlay);Map[c].Overlay=OVERLAY_BRICK_WALL;}
 auto target=new UnitClass(UNIT_MTANK,player?HOUSE_BAD:HOUSE_GOOD);Put(target,XY_Cell(Cell_X(center)+18,Cell_Y(center)));Check("blocked fixed exit uses a wider legal release cell",producer->Exit_Object(p)==2&&!p->IsInLimbo&&MAX(ABS(Cell_X(Coord_Cell(p->Coord))-Cell_X(center)),ABS(Cell_Y(Coord_Cell(p->Coord))-Cell_Y(center)))>4);if(!player)Check("enemy product receives immediate formation deployment",(Campaign_Formation_Holding(p)||p->Mission==MISSION_HUNT)&&Target_Legal(p->NavCom));for(auto entry:restore)Map[entry.first].Overlay=entry.second;
 // Complete obstruction: retain the already-paid object in limbo for retry.
 p=new UnitClass(UNIT_LTANK,house);restore.clear();for(int dy=-12;dy<=12;++dy)for(int dx=-12;dx<=12;++dx){CELL c=XY_Cell(Cell_X(center)+dx,Cell_Y(center)+dy);if(!Map.In_Radar(c)||Map[c].Cell_Building())continue;restore.emplace_back(c,Map[c].Overlay);Map[c].Overlay=OVERLAY_BRICK_WALL;}
 Check("fully blocked production waits without abandoning its product",producer->Exit_Object(p)==1&&p->IsActive&&p->IsInLimbo);
 FactoryClass* paid=nullptr;TARGET paidId=TARGET_NONE;int money=0;
 if(player){producer->Revealed(PlayerPtr);paid=new FactoryClass;Check("queue sidebar product behind a blocked exit",paid->Set(UnitTypeClass::As_Reference(UNIT_LTANK),*PlayerPtr)&&paid->Start());PlayerPtr->Set_Factory(RTTI_UNITTYPE,paid);for(int tick=0;tick<50000&&!paid->Has_Completed();++tick){++Frame;paid->AI();}money=PlayerPtr->Available_Money();paidId=paid->Get_Object()->As_Target();Check("sidebar blocked status never completes or discards the paid product",!PlayerPtr->Place_Object(RTTI_UNITTYPE,-1)&&paid->Get_Object()==As_Techno(paidId)&&paid->Get_Object()->IsInLimbo&&paid->Has_Completed()&&PlayerPtr->Available_Money()==money);}
 for(auto entry:restore)Map[entry.first].Overlay=entry.second;
 if(player){Check("sidebar retries the same paid product after blockage clears",PlayerPtr->Place_Object(RTTI_UNITTYPE,-1)&&As_Techno(paidId)&&!As_Techno(paidId)->IsInLimbo&&PlayerPtr->Available_Money()==money);}

}
static void AirstripTriples(const std::string& dir){Prepare(dir);auto strip=new BuildingClass(STRUCT_AIRSTRIP,HOUSE_BAD);Put(strip,Center());auto f=new FactoryClass;Check("queue airstrip tank",f->Set(UnitTypeClass::As_Reference(UNIT_LTANK),*Enemy())&&f->Start());for(int tick=0;tick<50000&&!f->Has_Completed();++tick){++Frame;f->AI();}auto obj=f->Get_Object();auto id=obj->As_Target();Check("airstrip keeps the actual paid product identity",strip->Exit_Object(obj)==2&&As_Techno(id)==obj&&!obj->IsInLimbo);f->Completed();delete f;Campaign_Enemies_Apply();Check("actual airstrip release retains exactly three produced vehicles",EnemyCount()==3);}
static void MobileMakeYard(const std::string& dir){auto yard=MakeYard(dir);Frame=10*60*TICKS_PER_SECOND;auto choice=Campaign_Expansion_Suggest(Enemy(),RTTI_UNITTYPE);Check("wealthy enemy chooses MCV to create new bases",choice==&UnitTypeClass::As_Reference(UNIT_MCV));auto mcv=new UnitClass(UNIT_MCV,HOUSE_BAD);Put(mcv,XY_Cell(Cell_X(Center())+6,Cell_Y(Center())+5));auto id=mcv->As_Target();Campaign_Enemies_Mark_Extra(mcv);mcv->Assign_Mission(MISSION_GUARD);mcv->Commence();auto planningStart=std::chrono::steady_clock::now();Campaign_Expansion_AI();std::printf("MCV PLANNING ms=%lld\n",(long long)std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-planningStart).count());Check("MCV is given a distant reachable expansion route",mcv->Mission==MISSION_MOVE&&Target_Legal(mcv->NavCom));TARGET goal=mcv->NavCom;Check("save moving expansion MCV",Save_Game((dir+"/mcv.sav").c_str(),"MCV EXPANSION ROUTE"));Check("reload moving expansion MCV",Load_Game((dir+"/mcv.sav").c_str()));mcv=As_Unit(id);Check("native destination persists across save reload",mcv&&mcv->NavCom==goal);
 int initial=CountBuilding(STRUCT_CONST);for(int tick=0;tick<10000&&As_Unit(id);++tick){++Frame;auto u=As_Unit(id);u->AI();if(Frame%15==0)Campaign_Expansion_AI();}Check("MCV actually drives and deploys into a second construction yard",!As_Unit(id)&&CountBuilding(STRUCT_CONST)==initial+1);Campaign_Expansion_AI();Check("new yard can select continued construction",Enemy()->IsStarted&&Enemy()->Suggest_New_Object(RTTI_BUILDINGTYPE));}
static long ResourceAmount(){long amount=0;for(int c=0;c<MAP_CELL_TOTAL;++c)if(Map[c].Land_Type()==LAND_TIBERIUM)amount+=Map[c].OverlayData+1;return amount;}
static void Growth(const std::string& dir){Prepare(dir);Special.IsTGrowth=true;Special.IsTSpread=true;Special.IsTFast=false;Check("save deterministic resource state",Save_Game((dir+"/growth.sav").c_str(),"GROWTH FOUR TIMES"));Scen.RandomNumber=123456;for(int i=0;i<3000;++i)Map.Logic();long native=ResourceAmount();Check("restore identical resource scan state",Load_Game((dir+"/growth.sav").c_str()));Scen.RandomNumber=123456;for(int i=0;i<150;++i)Campaign_Expansion_Resources();Check("150 accelerated ticks equal 3000 original growth and spread steps",ResourceAmount()==native);long accelerated=ResourceAmount();Check("restore resource state for ordinary rate",Load_Game((dir+"/growth.sav").c_str()));Scen.RandomNumber=123456;for(int i=0;i<150;++i)Map.Logic();std::printf("GROWTH normal=%ld accelerated=%ld\n",ResourceAmount(),accelerated);Check("twentyfold growth visibly increases resource stock over ordinary rate",ResourceAmount()<accelerated);}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);DistanceRule(dir);Construction(dir);GdiFortress(dir);AutonomousBuildings(dir);WideExit(dir,false);WideExit(dir,true);AirstripTriples(dir);MobileMakeYard(dir);Growth(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
